package com.example.starter.race.config;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

import java.time.Clock;

/**
 * 领域通用 Bean：系统 UTC 时钟；测试可替换为固定时钟。
 */
@Configuration
public class RaceConfig {

    @Bean
    public Clock clock() {
        return Clock.systemUTC();
    }
}

package com.example.starter.race.api;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

/**
 * 封榜请求；校验版本后原子保存全体选手只读成绩快照并转 SEALED。
 *
 * @param expectedVersion 客户端所见赛事版本
 * @param requestId       全局唯一请求ID（幂等键）
 */
public record SealRaceRequest(
        @NotNull Integer expectedVersion,
        @NotBlank String requestId
) {
}

package com.example.starter.race.api;

import com.example.starter.race.domain.RaceStatus;

/**
 * 赛事信息响应。
 *
 * @param raceId    赛事ID
 * @param version   当前版本号（从1开始）
 * @param status    OPEN / SEALED
 * @param createdAt 创建时间，Unix毫秒时间戳
 */
public record RaceResponse(String raceId, int version, RaceStatus status, long createdAt) {
}

package com.example.starter.race.api;

/**
 * 错误响应体。
 *
 * @param error   错误类型代码
 * @param message 可读错误信息
 */
public record ErrorResponse(String error, String message) {
}

package com.example.starter.race.domain;

/**
 * 选手成绩状态：RANKED-正常参与排名；UNTIMED-计时缺失不排名；DISQUALIFIED-存在生效取消资格处罚不排名。
 */
public enum EntryStatus {
    RANKED,
    UNTIMED,
    DISQUALIFIED
}

